class FileTime(ct.Structure):_fields_=[('low',w.DWORD),('high',w.DWORD)]
class MemoryCountersEx(ct.Structure):
    _fields_=[('cb',w.DWORD),('PageFaultCount',w.DWORD),('PeakWorkingSetSize',ct.c_size_t),('WorkingSetSize',ct.c_size_t),('QuotaPeakPagedPoolUsage',ct.c_size_t),('QuotaPagedPoolUsage',ct.c_size_t),('QuotaPeakNonPagedPoolUsage',ct.c_size_t),('QuotaNonPagedPoolUsage',ct.c_size_t),('PagefileUsage',ct.c_size_t),('PeakPagefileUsage',ct.c_size_t),('PrivateUsage',ct.c_size_t)]
assert ct.sizeof(ct.c_void_p)==8 and ct.sizeof(FileTime)==8 and ct.sizeof(MemoryCountersEx)==80
assert MemoryCountersEx.WorkingSetSize.offset==16 and MemoryCountersEx.PrivateUsage.offset==72
k=ct.WinDLL('kernel32',use_last_error=True);k.GetCurrentProcess.argtypes=[];k.GetCurrentProcess.restype=w.HANDLE;k.GetProcessTimes.argtypes=[w.HANDLE,*[ct.POINTER(FileTime)]*4];k.GetProcessTimes.restype=w.BOOL;k.K32GetProcessMemoryInfo.argtypes=[w.HANDLE,ct.POINTER(MemoryCountersEx),w.DWORD];k.K32GetProcessMemoryInfo.restype=w.BOOL;handle=k.GetCurrentProcess()
def sample():
    values=[FileTime()for _ in range(4)];assert k.GetProcessTimes(handle,*[ct.byref(x)for x in values]),ct.get_last_error();m=MemoryCountersEx();m.cb=ct.sizeof(m);assert k.K32GetProcessMemoryInfo(handle,ct.byref(m),ct.sizeof(m)),ct.get_last_error();v={name:int(getattr(m,name))for name,_ in m._fields_};v['CPU_ticks100ns']=sum((x.high<<32)|x.low for x in values[2:]);assert v['cb']==80 and v['PeakWorkingSetSize']>=v['WorkingSetSize']>0 and v['PeakPagefileUsage']>=v['PagefileUsage']>0 and v['PrivateUsage']>0;return v
before=sample();command=['powershell.exe','-NoProfile','-NonInteractive','-Command',"(Get-Counter -ListSet 'GPU Process Memory' -ErrorAction Stop).Paths | ConvertTo-Json -Compress"]
run=subprocess.run(command,text=True,capture_output=True,check=True,timeout=30,creationflags=subprocess.CREATE_NO_WINDOW);paths=json.loads(run.stdout);assert isinstance(paths,list)and any(x.endswith('\\Dedicated Usage')for x in paths)and any(x.endswith('\\Shared Usage')for x in paths);after=sample();assert after['CPU_ticks100ns']>=before['CPU_ticks100ns']
